CREATE TABLE IF NOT EXISTS public.admin_tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title varchar(160) NOT NULL, task_type smallint NOT NULL CHECK(task_type BETWEEN 0 AND 3), notes text, due_date date NOT NULL, completed_at timestamptz, completed_by_user_id uuid REFERENCES public.users(id), created_by_user_id uuid NOT NULL REFERENCES public.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.admin_task_orders (task_id uuid NOT NULL REFERENCES public.admin_tasks(id) ON DELETE CASCADE, order_id uuid NOT NULL REFERENCES public.orders(id), completed_at timestamptz, completed_by_user_id uuid REFERENCES public.users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(task_id,order_id));
CREATE INDEX IF NOT EXISTS ix_admin_tasks_due_date ON public.admin_tasks(due_date); CREATE INDEX IF NOT EXISTS ix_admin_tasks_completed_at ON public.admin_tasks(completed_at); CREATE INDEX IF NOT EXISTS ix_admin_task_orders_order_id ON public.admin_task_orders(order_id);
